using System.Net;
using System.Text;
using System.Text.Json;
using PaymentAuthorization.Domain;
using PaymentAuthorization.Infrastructure;

namespace PaymentAuthorization.IntegrationTest.PaymentGateway;

public sealed class HttpPaymentGatewayTests : IAsyncLifetime
{
    private readonly FakeProvider provider = new();

    public Task InitializeAsync() => Task.CompletedTask;

    public async Task DisposeAsync() => await provider.DisposeAsync();

    private HttpPaymentGateway Gateway() => new(new HttpClient { BaseAddress = provider.BaseAddress });

    [Fact]
    public async Task The_authorization_is_sent_as_a_JSON_POST_with_reference_amount_and_currency()
    {
        provider.Respond(200, """{"status":"approved"}""");

        await Gateway().AuthorizeAsync("ORD-7", new Money(12.5m, "eur"), CancellationToken.None);

        var received = Assert.Single(provider.Requests);
        Assert.Equal("POST", received.Method);
        Assert.Equal("/v1/authorizations", received.Path);
        Assert.StartsWith("application/json", received.ContentType);
        using var json = JsonDocument.Parse(received.Body);
        var root = json.RootElement;
        Assert.Equal("ORD-7", root.GetProperty("reference").GetString());
        Assert.Equal(12.5m, root.GetProperty("amount").GetDecimal());
        Assert.Equal("EUR", root.GetProperty("currency").GetString());
        Assert.Equal(3, root.EnumerateObject().Count());
    }

    [Fact]
    public async Task An_approved_status_is_read_as_approved()
    {
        provider.Respond(200, """{"status":"approved"}""");

        var outcome = await Gateway().AuthorizeAsync("A", new Money(1, "EUR"), CancellationToken.None);

        Assert.Equal(AuthorizationOutcome.Approved, outcome);
    }

    [Fact]
    public async Task A_declined_status_is_read_as_declined()
    {
        provider.Respond(200, """{"status":"declined"}""");

        var outcome = await Gateway().AuthorizeAsync("A", new Money(1, "EUR"), CancellationToken.None);

        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Fact]
    public async Task Extra_fields_in_the_answer_are_ignored()
    {
        provider.Respond(200, """{"id":"x1","status":"approved","risk":{"score":3}}""");

        var outcome = await Gateway().AuthorizeAsync("A", new Money(1, "EUR"), CancellationToken.None);

        Assert.Equal(AuthorizationOutcome.Approved, outcome);
    }

    [Fact]
    public async Task A_402_refusal_is_read_as_declined()
    {
        provider.Respond(402, """{"error":"card_refused"}""");

        var outcome = await Gateway().AuthorizeAsync("A", new Money(1, "EUR"), CancellationToken.None);

        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Theory]
    [InlineData("""{}""")]
    [InlineData("""{"status":null}""")]
    [InlineData("""{"state":"approved"}""")]
    [InlineData("""{"status":"APPROVED"}""")]
    [InlineData("""null""")]
    public async Task An_answer_without_an_exact_approved_status_is_never_treated_as_approved(string body)
    {
        provider.Respond(200, body);

        var outcome = await Gateway().AuthorizeAsync("A", new Money(1, "EUR"), CancellationToken.None);

        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Fact]
    public async Task An_answer_that_is_not_JSON_is_surfaced_as_an_error()
    {
        provider.Respond(200, "<html>oops</html>");

        await Assert.ThrowsAnyAsync<JsonException>(() =>
            Gateway().AuthorizeAsync("A", new Money(1, "EUR"), CancellationToken.None));
    }

    [Theory]
    [InlineData(400)]
    [InlineData(401)]
    [InlineData(404)]
    [InlineData(500)]
    [InlineData(503)]
    public async Task Other_failures_are_surfaced_as_errors_not_as_a_decision(int status)
    {
        provider.Respond(status, """{"status":"approved"}""");

        var error = await Assert.ThrowsAsync<HttpRequestException>(() =>
            Gateway().AuthorizeAsync("A", new Money(1, "EUR"), CancellationToken.None));

        Assert.Equal((HttpStatusCode)status, error.StatusCode);
    }

    private sealed record ReceivedRequest(string Method, string Path, string? ContentType, string Body);

    private sealed class FakeProvider : IAsyncDisposable
    {
        private readonly HttpListener listener = new();
        private readonly Task loop;
        private int status = 200;
        private string body = "{}";

        public FakeProvider()
        {
            var port = FreePort();
            BaseAddress = new Uri($"http://127.0.0.1:{port}");
            listener.Prefixes.Add($"http://127.0.0.1:{port}/");
            listener.Start();
            loop = Task.Run(Serve);
        }

        public Uri BaseAddress { get; }

        public List<ReceivedRequest> Requests { get; } = [];

        public void Respond(int statusCode, string responseBody)
        {
            status = statusCode;
            body = responseBody;
        }

        private async Task Serve()
        {
            while (listener.IsListening)
            {
                HttpListenerContext context;
                try { context = await listener.GetContextAsync(); }
                catch (Exception) { return; }

                using var reader = new StreamReader(context.Request.InputStream, Encoding.UTF8);
                var requestBody = await reader.ReadToEndAsync();
                lock (Requests)
                {
                    Requests.Add(new ReceivedRequest(
                        context.Request.HttpMethod,
                        context.Request.Url!.AbsolutePath,
                        context.Request.ContentType,
                        requestBody));
                }

                var bytes = Encoding.UTF8.GetBytes(body);
                context.Response.StatusCode = status;
                context.Response.ContentType = "application/json";
                await context.Response.OutputStream.WriteAsync(bytes);
                context.Response.Close();
            }
        }

        private static int FreePort()
        {
            var probe = new System.Net.Sockets.TcpListener(IPAddress.Loopback, 0);
            probe.Start();
            var port = ((IPEndPoint)probe.LocalEndpoint).Port;
            probe.Stop();
            return port;
        }

        public async ValueTask DisposeAsync()
        {
            listener.Close();
            await loop;
        }
    }
}
